styles.add(ParagraphStyle(name='TitleX',fontName='Helvetica-Bold',fontSize=25,leading=29,spaceAfter=14,textColor=colors.HexColor('#123b61')))
styles.add(ParagraphStyle(name='HeadX',fontName='Helvetica-Bold',fontSize=15,leading=19,spaceBefore=10,spaceAfter=10,textColor=colors.HexColor('#123b61')))
styles.add(ParagraphStyle(name='SmallX',fontName='Helvetica',fontSize=8.5,leading=11,spaceAfter=6))
